mapper.select:
SELECT code_hash, expires_at, verified_at, failed_attempts, resend_window_started_at, resend_count
FROM email_verification WHERE email = #{email}
AND purpose = #{purpose}
FOR UPDATE

mapper.update:
UPDATE email_verification
SET code_hash = #{codeHash}, expires_at = #{expiresAt}, verified_at = NULL,
failed_attempts = 0, resend_window_started_at = #{windowStartedAt}, resend_count = #{resendCount}
WHERE email = #{email} AND purpose = #{purpose}

UPDATE email_verification
SET failed_attempts = #{failedAttempts}
WHERE email = #{email}
AND purpose = #{purpose}

UPDATE email_verification
SET verified_at = #{verifiedAt}
WHERE email = #{email}
AND purpose = #{purpose}

UPDATE email_verification
SET verified_at = NULL, expires_at = #{usedAt}
WHERE email = #{email}
AND purpose = #{purpose}
AND verified_at IS NOT NULL
